// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.voice.synthimport com.roshan.persona.voice.tts.VoicePersona/** * NOUS — Audio Synthesizer data model (§14 Audio Synthesizer / Sound Effects). * * Sound effects and tones NOUS plays to communicate state to the user * (boot chime, success/error feedback, idle arc-reactor hum). Distinct from * TTS — these are *non-verbal* audio cues that convey meaning faster than * speech ("the task is done" — a 200 ms chime vs a 2 s spoken "Done, sir."). * * ## Why sound effects? (§25 Q8) * * Per confirmed decision Q8, all sound effects are toggleable in Settings. * Audio UI communicates state faster than speech — a 200 ms chime tells the * user "task done" without requiring them to listen to a sentence. This is * especially valuable when the user is driving (eyes on road, can't read * notifications) or wearing earphones (chime is less disruptive than speech). * * ## The 5 sound effects (§14) * * | Effect               | Use case                                  | * |----------------------|-------------------------------------------| * | ARC_REACTOR_HUM      | Idle ambiance — NOUS is alive, listening  | * | BOOT_STARTUP         | App startup — initialization complete     | * | NOTIFICATION_CHIME   | Per-persona chime for notifications       | * | ERROR_SUBTLE         | Non-jarring error indicator               | * | SUCCESS              | Task completed successfully               | * * ## Tones vs effects * * Two kinds of audio output: *  - **[SoundEffect]** — pre-recorded .wav files played from assets. Higher *    quality (multi-instrument, layered), but fixed. *  - **[ToneSpec]** — programmatic sine-wave tones generated on the fly. *    Lower quality, but flexible (any frequency / duration / volume) and *    zero asset storage. Used for in-app cues (button click, error beep). * * @see <a href="docs/strategy/module-5-strategy-v2.md">§14 Audio Synthesizer (Sound Effects), §25 Q8 toggleable</a> *//** * Pre-recorded sound effects (§14). * * Files live in `:feature:voice/src/main/assets/sounds/`. Each effect maps * to a .wav file via [filePath]. * * @param filePath path under assets/ (e.g. "sounds/boot.wav"). * @param defaultVolume 0.0–1.0 — default playback volume (can be overridden *                       per call). */enum class SoundEffect(    val filePath: String,    val defaultVolume: Float = 0.5f,) {    /** Idle ambiance — arc reactor hum while NOUS is listening (loopable). */    ARC_REACTOR_HUM("sounds/arc_reactor_hum.wav", defaultVolume = 0.15f),    /** App startup — initialization complete. */    BOOT_STARTUP("sounds/boot.wav", defaultVolume = 0.7f),    /** Per-persona notification chime. */    NOTIFICATION_CHIME("sounds/chime.wav", defaultVolume = 0.5f),    /** Subtle, non-jarring error indicator. */    ERROR_SUBTLE("sounds/error.wav", defaultVolume = 0.4f),    /** Task completed successfully. */    SUCCESS("sounds/success.wav", defaultVolume = 0.6f);    init {        require(defaultVolume in 0f..1f) {            "$name defaultVolume $defaultVolume out of [0,1]"        }    }}// ──────────────────────────────────────────────────────────────────────────/** * Specification for one programmatically-generated tone. * * Used by [AudioSynthesizer.generateTone] to synthesize a sine wave on the * fly — useful for short UI cues (button click, error beep, confirmation) * where loading a .wav file would be overkill. * * @param frequencyHz  tone frequency (20 Hz – 20 kHz; human hearing range). * @param durationMs   tone duration in milliseconds (1 ms – 10 s). * @param volume       0.0–1.0 (1.0 = max). * @param waveform     sine (default), square, triangle, or sawtooth. */data class ToneSpec(    val frequencyHz: Int,    val durationMs: Long,    val volume: Float = 0.5f,    val waveform: Waveform = Waveform.SINE,) {    init {        require(frequencyHz in 20..20_000) {            "frequencyHz must be 20..20000, got $frequencyHz"        }        require(durationMs in 1..10_000) {            "durationMs must be 1..10000, got $durationMs"        }        require(volume in 0f..1f) {            "volume must be in [0,1], got $volume"        }    }    companion object {        /** Common UI tone: soft confirmation beep (880 Hz, 100 ms, sine). */        val CONFIRMATION_BEEP = ToneSpec(880, 100, volume = 0.3f)        /** Common UI tone: error buzz (220 Hz, 200 ms, square). */        val ERROR_BUZZ = ToneSpec(220, 200, volume = 0.4f, waveform = Waveform.SQUARE)        /** Common UI tone: subtle click (1 kHz, 30 ms, sine). */        val SUBTLE_CLICK = ToneSpec(1000, 30, volume = 0.2f)    }}// ──────────────────────────────────────────────────────────────────────────/** Waveform shape for [ToneSpec]. */enum class Waveform {    /** Pure sine wave — smooth, natural. Default for most tones. */    SINE,    /** Square wave — buzzy, attention-grabbing. Good for error beeps. */    SQUARE,    /** Triangle wave — soft, mellow. Good for confirmation chimes. */    TRIANGLE,    /** Sawtooth wave — harsh, bright. Good for retro UI sounds. */    SAWTOOTH,}// ──────────────────────────────────────────────────────────────────────────/** * Per-persona notification chime spec (§14 NOTIFICATION_CHIME). * * Each persona has a distinct chime so the user can identify which persona * is active without looking at the screen. Chimes are short (< 500 ms) and * non-intrusive. * * Mapping is intentional: *  - JARVIS → dignified, lower-pitched (440 Hz) *  - FRIDAY → bright, higher-pitched (660 Hz) *  - ULTRON → cold, dissonant (220 Hz square) *  - etc. */object PersonaChimeMapping {    /** Get the chime spec for a persona. */    fun chimeFor(persona: VoicePersona): ToneSpec = when (persona) {        VoicePersona.ATLAS    -> ToneSpec(440, 300, volume = 0.4f, waveform = Waveform.SINE)        VoicePersona.NOVA     -> ToneSpec(660, 250, volume = 0.4f, waveform = Waveform.SINE)        VoicePersona.ONYX     -> ToneSpec(220, 350, volume = 0.4f, waveform = Waveform.SQUARE)        VoicePersona.SAGE     -> ToneSpec(523, 280, volume = 0.35f, waveform = Waveform.TRIANGLE)        VoicePersona.ECHO     -> ToneSpec(587, 260, volume = 0.4f, waveform = Waveform.SINE)        VoicePersona.VANGUARD -> ToneSpec(392, 320, volume = 0.4f, waveform = Waveform.SINE)        VoicePersona.ARIA     -> ToneSpec(740, 240, volume = 0.45f, waveform = Waveform.SINE)        VoicePersona.WRAITH   -> ToneSpec(330, 300, volume = 0.3f, waveform = Waveform.SAWTOOTH)        VoicePersona.ZENITH   -> ToneSpec(494, 280, volume = 0.35f, waveform = Waveform.TRIANGLE)    }}// ──────────────────────────────────────────────────────────────────────────/** * Configuration for the [AudioSynthesizer]. * * @param sampleRate        PCM sample rate (default 44.1 kHz — CD quality). * @param masterVolume      0.0–1.0 master multiplier applied to all output. * @param enabled           if false, all sound effects and tones are silent *                            (per §25 Q8 — user can disable in Settings). * @param arcReactorHumEnabled  if true (default), the arc reactor hum plays *                            while NOUS is idle/listening. Some users find *                            it creepy; they can disable it independently. */data class AudioSynthesizerConfig(    val sampleRate: Int = DEFAULT_SAMPLE_RATE,    val masterVolume: Float = 1.0f,    val enabled: Boolean = true,    val arcReactorHumEnabled: Boolean = true,) {    init {        require(sampleRate in 8_000..48_000) {            "sampleRate must be 8000..48000, got $sampleRate"        }        require(masterVolume in 0f..1f) {            "masterVolume must be in [0,1], got $masterVolume"        }    }    companion object {        const val DEFAULT_SAMPLE_RATE = 44_100    }}